import { phase } from '/tmp/probe/p.mjs';
// Batch many snippets into one document, separated by marker paragraphs.
export function multi(slot, items) {
  const doc = items.map((t,i)=>`ZQ${i}Q\n\n${t}`).join('\n\n') + `\n\nZQ${items.length}Q`;
  const out = phase(slot, doc);
  const res = [];
  for (let i=0;i<items.length;i++){
    const a = out.indexOf(`<p>ZQ${i}Q</p>`);
    const b = out.indexOf(`<p>ZQ${i+1}Q</p>`);
    if (a<0||b<0) { res.push('SPLIT_FAIL'); continue; }
    res.push(out.slice(a + `<p>ZQ${i}Q</p>`.length, b).replace(/^\n+/,'').replace(/\n+$/,''));
  }
  return res;
}
EOF
